{"command":"cd /workspace; cat > args.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"
	"net/url"
	"os"
	"strings"
)

// Opts is a flat list of command line arguments passed to curl.
type Opts []string

func flagName(name string) string {
	if len(name) == 1 {
		return "-" + name
	}
	return "--" + name
}

// Has reports whether the option is present in the list.
func (o Opts) Has(name string) bool {
	f := flagName(name)
	for _, v := range o {
		if v == f {
			return true
		}
	}
	return false
}

// Val returns the value following the first occurrence of the option.
func (o Opts) Val(name string) string {
	f := flagName(name)
	for i, v := range o {
		if v == f {
			if i+1 < len(o) {
				return o[i+1]
			}
			return ""
		}
	}
	return ""
}

// Remove deletes all occurrences of the option and reports whether any was found.
func (o *Opts) Remove(name string) bool {
	f := flagName(name)
	found := false
	out := (*o)[:0]
	for _, v := range *o {
		if v == f {
			found = true
			continue
		}
		out = append(out, v)
	}
	*o = out
	return found
}

var shortWithArg = map[byte]bool{}

func init() {
	for _, c := range []byte("bcdehmortuwxyzACDEFHKPQTUXY") {
		shortWithArg[c] = true
	}
}

var longWithArg = map[string]bool{}

func init() {
	for _, n := range strings.Fields(`
abstract-unix-socket alt-svc aws-sigv4 cacert capath cert cert-type ciphers
config connect-timeout connect-to continue-at cookie cookie-jar
create-file-mode crlfile curves data data-ascii data-binary data-raw
data-urlencode delegation dns-interface dns-ipv4-addr dns-ipv6-addr
dns-servers doh-url dump-header ech egd-file engine etag-compare etag-save
expect100-timeout form form-string ftp-account ftp-alternative-to-user
ftp-method ftp-port ftp-ssl-ccc-mode happy-eyeballs-timeout-ms
haproxy-clientip header help hostpubmd5 hostpubsha256 hsts interface ip-tos
ipfs-gateway json keepalive-cnt keepalive-time key key-type krb libcurl
limit-rate local-port login-options mail-auth mail-from mail-rcpt
max-filesize max-redirs max-time netrc-file noproxy oauth2-bearer output
output-dir parallel-max pass pinnedpubkey preproxy proto proto-default
proto-redir proxy proxy-cacert proxy-capath proxy-cert proxy-cert-type
proxy-ciphers proxy-crlfile proxy-header proxy-key proxy-key-type proxy-pass
proxy-pinnedpubkey proxy-service-name proxy-tls13-ciphers proxy-tlsauthtype
proxy-tlspassword proxy-tlsuser proxy-user proxy1.0 pubkey quote random-file
range rate referer request request-target resolve retry retry-delay
retry-max-time sasl-authzid service-name sigalgs socks4 socks4a socks5
socks5-gssapi-service socks5-hostname speed-limit speed-time ssl-sessions
stderr telnet-option tftp-blksize time-cond tls-max tls13-ciphers
tlsauthtype tlspassword tlsuser trace trace-ascii trace-config unix-socket
upload-file upload-flags url url-query user user-agent variable
vlan-priority write-out
`) {
		longWithArg[n] = true
	}
}

func longTakesArg(name string) bool {
	if longWithArg[name] {
		return true
	}
	if strings.HasPrefix(name, "expand-") {
		return longWithArg[strings.TrimPrefix(name, "expand-")]
	}
	return false
}

var methods = map[string]bool{
	"GET": true, "POST": true, "PUT": true, "PATCH": true,
	"DELETE": true, "HEAD": true, "OPTIONS": true, "TRACE": true,
}

// Parse converts the program arguments into curl options, translating
// httpie-like request items along the way.
func Parse(argv []string) Opts {
	opts := Opts{}
	form := false
	args := make([]string, 0, len(argv))
	for _, a := range argv[1:] {
		if a == "-F" || a == "--form" {
			form = true
			continue
		}
		args = append(args, a)
	}

	method := ""
	rawURL := ""
	hasURL := false
	var items []string
	var query []string
	data := map[string]interface{}{}
	hasData := false
	dashdash := false

	for i := 0; i < len(args); i++ {
		a := args[i]
		if !dashdash && len(a) > 1 && a[0] == '-' {
			if a == "--" {
				dashdash = true
				continue
			}
			if a[1] == '-' {
				opts = append(opts, a)
				if longTakesArg(a[2:]) && i+1 < len(args) {
					i++
					opts = append(opts, args[i])
				}
				continue
			}
			for j := 1; j < len(a); j++ {
				c := a[j]
				opts = append(opts, string([]byte{'-', c}))
				if shortWithArg[c] {
					if j+1 < len(a) {
						opts = append(opts, a[j+1:])
					} else if i+1 < len(args) {
						i++
						opts = append(opts, args[i])
					}
					break
				}
			}
			continue
		}
		if !hasURL && method == "" && methods[strings.ToUpper(a)] {
			method = strings.ToUpper(a)
			continue
		}
		if !hasURL {
			rawURL = a
			hasURL = true
			continue
		}
		idx := strings.IndexAny(a, ":=")
		if idx == -1 {
			items = append(items, a)
			continue
		}
		if a[idx] == ':' {
			if idx+1 < len(a) && a[idx+1] == '=' {
				var v interface{}
				_ = json.Unmarshal([]byte(a[idx+2:]), &v)
				data[a[:idx]] = v
				hasData = true
			} else {
				items = append(items, "-H", a)
			}
			continue
		}
		// '='
		if idx+1 < len(a) && a[idx+1] == '=' {
			query = append(query, url.QueryEscape(a[:idx])+"="+url.QueryEscape(a[idx+2:]))
			continue
		}
		if form {
			items = append(items, "-F", a)
			continue
		}
		data[a[:idx]] = a[idx+1:]
		hasData = true
	}

	if method == "HEAD" {
		opts = append(opts, "-I")
	} else if method != "" {
		opts = append(opts, "-X", method)
	}
	opts = append(opts, items...)
	if hasData {
		b, _ := json.Marshal(data)
		opts = append(opts, "-d", string(b))
	}
	if hasURL {
		u := rawURL
		for _, q := range query {
			if strings.IndexByte(u, '?') != -1 {
				u += "&" + q
			} else {
				u += "?" + q
			}
		}
		opts = append(opts, fixURL(u))
	}
	return opts
}

func fixURL(s string) string {
	u := s
	added := false
	if !strings.HasPrefix(u, "http://") && !strings.HasPrefix(u, "https://") {
		u = "http://" + u
		added = true
	}
	fmt.Fprintln(os.Stderr, u)
	pu, err := url.Parse(u)
	if err != nil {
		fmt.Print(err)
		return u
	}
	if pu.Host == ":" {
		pu.Host = "localhost"
	} else if strings.HasPrefix(pu.Host, ":") {
		pu.Host = "localhost" + pu.Host
	}
	r := pu.String()
	if added {
		r = strings.TrimPrefix(r, "http://")
	}
	return r
}
EOF"}

