`) {
		longWithArg[n] = true
	}
}

func longTakesArg(name string) bool {
	if longWithArg[name] {
		return true
	}
	if strings.HasPrefix(name, "expand-") {
		return longWithArg[strings.TrimPrefix(name, "expand-")]
	}
	return false
}

var methods = map[string]bool{
	"GET": true, "POST": true, "PUT": true, "PATCH": true,
	"DELETE": true, "HEAD": true, "OPTIONS": true, "TRACE": true,
}

// Parse converts the program arguments into curl options, translating
// httpie-like request items along the way.
func Parse(argv []string) Opts {
	opts := Opts{}
	form := false
	args := make([]string, 0, len(argv))
	for _, a := range argv[1:] {
		if a == "-F" || a == "--form" {
			form = true
			continue
		}
		args = append(args, a)
	}

	method := ""
	rawURL := ""
	hasURL := false
	var items []string
	var query []string
	data := map[string]interface{}{}
	hasData := false
	dashdash := false

	for i := 0; i < len(args); i++ {
		a := args[i]
		if !dashdash && len(a) > 1 && a[0] == '-' {
			if a == "--" {
				dashdash = true
				continue
			}
			if a[1] == '-' {
				opts = append(opts, a)
				if longTakesArg(a[2:]) && i+1 < len(args) {
					i++
					opts = append(opts, args[i])
				}
				continue
			}
			for j := 1; j < len(a); j++ {
				c := a[j]
				opts = append(opts, string([]byte{'-', c}))
				if shortWithArg[c] {
					if j+1 < len(a) {
						opts = append(opts, a[j+1:])
					} else if i+1 < len(args) {
						i++
						opts = append(opts, args[i])
					}
					break
				}
			}
			continue
		}
		if !hasURL && method == "" && methods[strings.ToUpper(a)] {
			method = strings.ToUpper(a)
			continue
		}
		if !hasURL {
			rawURL = a
			hasURL = true
			continue
		}
		idx := strings.IndexAny(a, ":=")
		if idx == -1 {
			items = append(items, a)
			continue
		}
		if a[idx] == ':' {
			if idx+1 < len(a) && a[idx+1] == '=' {
				var v interface{}
				_ = json.Unmarshal([]byte(a[idx+2:]), &v)
				data[a[:idx]] = v
				hasData = true
			} else {
				items = append(items, "-H", a)
			}
			continue
		}
		// '='
		if idx+1 < len(a) && a[idx+1] == '=' {
			query = append(query, url.QueryEscape(a[:idx])+"="+url.QueryEscape(a[idx+2:]))
			continue
		}
		if form {
			items = append(items, "-F", a)
			continue
		}
		data[a[:idx]] = a[idx+1:]
		hasData = true
	}

	if method == "HEAD" {
		opts = append(opts, "-I")
	} else if method != "" {
		opts = append(opts, "-X", method)
	}
	opts = append(opts, items...)
	if hasData {
		b, _ := json.Marshal(data)
		opts = append(opts, "-d", string(b))
	}
	if hasURL {
		u := rawURL
		for _, q := range query {
			if strings.IndexByte(u, '?') != -1 {
				u += "&" + q
			} else {
				u += "?" + q
			}
		}
		opts = append(opts, fixURL(u))
	}
	return opts
}

func fixURL(s string) string {
	u := s
	added := false
	if !strings.HasPrefix(u, "http://") && !strings.HasPrefix(u, "https://") {
		u = "http://" + u
		added = true
	}
	fmt.Fprintln(os.Stderr, u)
	pu, err := url.Parse(u)
	if err != nil {
		fmt.Print(err)
		return u
	}
	if pu.Host == ":" {
		pu.Host = "localhost"
	} else if strings.HasPrefix(pu.Host, ":") {
		pu.Host = "localhost" + pu.Host
	}
	r := pu.String()
	if added {
		r = strings.TrimPrefix(r, "http://")
	}
	return r
}
