}

func newJSONFormatter(out io.Writer, s ColorScheme) *jsonFormatter {
	return &jsonFormatter{out: out, scheme: s}
}

func (f *jsonFormatter) newline(b []byte) []byte {
	b = append(b, '\n')
	for i := 0; i < f.depth; i++ {
		b = append(b, "    "...)
	}
	return b
}

func (f *jsonFormatter) Write(p []byte) (int, error) {
	if !f.started && len(p) > 0 {
		f.started = true
		if p[0] != '{' && p[0] != '[' {
			f.passthru = true
		}
	}
	if f.passthru {
		_, err := f.out.Write(p)
		return len(p), err
	}
	b := f.buf[:0]
	for _, c := range p {
		if f.inStr {
			b = append(b, c)
			if c == '"' && f.prev != '\\' {
				f.inStr = false
			}
			f.prev = c
			f.last = c
			continue
		}
		switch c {
		case ' ', '\t', '\n', '\r':
			continue
		case '{', '[':
			f.depth++
			f.isValue = false
			b = append(b, f.scheme.Default...)
			b = append(b, c)
			b = f.newline(b)
		case '}', ']':
			f.depth--
			b = f.newline(b)
			b = append(b, f.scheme.Default...)
			b = append(b, c)
			if f.depth <= 0 {
				b = append(b, '\n')
				b = append(b, f.scheme.Reset...)
			}
		case ',':
			f.isValue = false
			b = append(b, f.scheme.Default...)
			b = append(b, ',')
			b = f.newline(b)
		case ':':
			f.isValue = true
			b = append(b, f.scheme.Default...)
			b = append(b, ':', ' ')
		case '"':
			f.inStr = true
			f.prev = c
			if f.isValue {
				b = append(b, f.scheme.Value...)
			} else {
				b = append(b, f.scheme.Key...)
			}
			b = append(b, c)
		default:
			if f.last == ':' {
				if c == 't' || c == 'f' || c == 'n' {
					b = append(b, f.scheme.Literal...)
				} else {
					b = append(b, f.scheme.Value...)
				}
			}
			b = append(b, c)
		}
		f.last = c
	}
	f.buf = b
	_, err := f.out.Write(b)
	return len(p), err
}

// ---------------------------------------------------------------------------
