type helpAdapter struct {
	out  io.Writer
	name string
}

func (h *helpAdapter) Write(p []byte) (int, error) {
	repl := []byte(h.name + " [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]")
