func leadChar(line []byte) (byte, int) {
	i := 0
	if bytes.HasPrefix(line, []byte("\x1b[")) {
		i = bytes.IndexByte(line, 'm') + 1
	}
	return line[i], i
}

func (h *headerCleaner) Write(p []byte) (int, error) {
	n := len(p)
	data := make([]byte, 0, len(h.pending)+len(p))
	data = append(data, h.pending...)
	data = append(data, p...)
	h.pending = h.pending[:0]
	b := h.buf[:0]
	for len(data) > 0 {
		idx := bytes.IndexByte(data, '\n')
		if idx == -1 {
			h.pending = append(h.pending, data...)
			break
		}
		line := data[:idx+1]
		data = data[idx+1:]
		skip := false
		c, i := leadChar(line)
		switch c {
		case '>':
			if h.verbose {
				line = line[i+2:]
			} else {
				skip = true
			}
		case '<':
			line = line[i+2:]
		case '{', '}':
			skip = true
			if h.verbose && h.post != nil {
				b = append(b, bytes.TrimSpace(h.post.Bytes())...)
				b = append(b, '\n', '\n')
				h.post = nil
			}
		case '*':
			if !h.verbose {
				skip = true
			}
		}
		if !skip {
			b = append(b, line...)
		}
	}
	h.buf = b
	_, err := h.out.Write(b)
	return n, err
}

