		b = append(append(b, s.Key...), m[1]...)
		b = append(append(b, s.Default...), m[2]...)
		b = append(append(b, s.Value...), m[3]...)
		b = append(append(b, s.Status...), m[4]...)
		return append(b, s.Reset...)
	}
	if m := headerLineRe.FindSubmatch(line); m != nil {
		b = append(append(b, s.Default...), m[1]...)
		b = append(append(b, s.Value...), m[2]...)
		return append(b, s.Reset...)
	}
	return append(b, line...)
