		if idx == -1 {
			b = h.colorize(b, p)
			break
		}
		b = h.colorize(b, p[:idx])
		b = append(b, '\n')
		p = p[idx+1:]
	}
	h.buf = b
	_, err := h.out.Write(b)
	return n, err
}
