package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"unsafe"
)

const (
	version = "v0.0.0-LOCAL"
	date    = "0000-00-00T00:00:00Z"
)

func isTerminal(fd int) bool {
	var t syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	return errno == 0
}

func headerSupplied(opts Opts, name string) bool {
	prefix := strings.ToLower(name) + ":"
	for i, o := range opts {
		if (o == "-H" || o == "--header") && i+1 < len(opts) {
			if strings.HasPrefix(strings.ToLower(opts[i+1]), prefix) {
				return true
			}
		}
	}
	return false
}

func main() {
	if len(os.Args) == 2 && os.Args[1] == "version" {
		fmt.Printf("curlie %s (%s)\n", version, date)
		os.Exit(0)
	}

	scheme := defaultScheme
	var stdout io.Writer = os.Stdout
	var stderr io.Writer = os.Stderr
	var stdin io.Reader = os.Stdin
