			if f.depth == 0 && !noReset {
				b = append(b, '\\n')
				b = append(b, f.scheme.Reset...)
			}
		case ',':
			f.isValue = false
			b = append(b, f.scheme.Default...)
			b = append(b, ',')
			b = f.newline(b)
		case ':':
			f.isValue = true
			b = append(b, f.scheme.Default...)
			b = append(b, ':', ' ')
		case '"':
			f.inStr = true
			if f.isValue {
				b = append(b, f.scheme.Value...)
			} else {
				b = append(b, f.scheme.Key...)
			}
			b = append(b, c)
		default:
			if f.last == ':' {
				if c == 't' || c == 'f' || c == 'n' {
					b = append(b, f.scheme.Literal...)
				} else {
					b = append(b, f.scheme.Value...)
				}
			}
			b = append(b, c)
		}
		f.last = c
	}
	f.buf = b
	_, err := f.out.Write(b)
	return len(p), err
}

'''
s = s[:old_start] + new + s[old_end:]
open('formatter.go', 'w').write(s)
EOF
